import React, { useState, useEffect } from "react";
import "./UserDashboard.css";

export default function UserDashboard() {
  const [checkIn, setCheckIn] = useState(null);
  const [checkOut, setCheckOut] = useState(null);
  const [timer, setTimer] = useState("00:00:00");
  const [history, setHistory] = useState([]);

  const [filter, setFilter] = useState("all");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");

  /* ================= TIMER ================= */
  useEffect(() => {
    let interval;
    if (checkIn && !checkOut) {
      interval = setInterval(() => {
        const now = new Date();
        const diff = now - checkIn;

        const hrs = String(Math.floor(diff / 3600000)).padStart(2, "0");
        const mins = String(
          Math.floor((diff % 3600000) / 60000)
        ).padStart(2, "0");
        const secs = String(
          Math.floor((diff % 60000) / 1000)
        ).padStart(2, "0");

        setTimer(`${hrs}:${mins}:${secs}`);
      }, 1000);
    }

    return () => clearInterval(interval);
  }, [checkIn, checkOut]);

  /* ================= CHECK IN ================= */
  const handleCheckIn = () => {
    if (checkIn) return alert("Already checked in!");
    setCheckIn(new Date());
    setCheckOut(null);
  };

  /* ================= CHECK OUT ================= */
  const handleCheckOut = () => {
    if (!checkIn) return alert("Check in first!");

    const now = new Date();
    const diffMs = now - checkIn;
    const diffHours = diffMs / (1000 * 60 * 60);

    if (diffHours < 9) {
      const remaining = 9 * 3600000 - diffMs;
      const hrs = Math.floor(remaining / 3600000);
      const mins = Math.floor((remaining % 3600000) / 60000);
      return alert(`⏳ Remaining: ${hrs}h ${mins}m`);
    }

    setCheckOut(now);

    setHistory([
      ...history,
      {
        date: new Date().toISOString().split("T")[0],
        checkIn: checkIn.toLocaleTimeString(),
        checkOut: now.toLocaleTimeString(),
        hours: diffHours.toFixed(2),
      },
    ]);
  };

  /* ================= FILTER LOGIC ================= */
  const filteredHistory = history.filter((item) => {
    const itemDate = new Date(item.date);
    const today = new Date();

    if (filter === "today") {
      return itemDate.toDateString() === today.toDateString();
    }

    if (filter === "month") {
      return (
        itemDate.getMonth() === today.getMonth() &&
        itemDate.getFullYear() === today.getFullYear()
      );
    }

    if (filter === "range" && fromDate && toDate) {
      return (
        itemDate >= new Date(fromDate) &&
        itemDate <= new Date(toDate)
      );
    }

    return true;
  });

  return (
    <div className="dashboard">
      {/* PROFILE */}
      <div className="profile-card">
        <img src="https://i.imgur.com/4Z7mK2K.png" alt="employee" />
        <h2>Harsha Reddy</h2>
        <p>Frontend Developer</p>
        <p className="id">EMP1023</p>
        <button className="logout" onClick={() => window.location.reload()}>
          Logout
        </button>
      </div>

      {/* ATTENDANCE */}
      <div className="attendance-card">
        <h3>Attendance Dashboard</h3>

        <div className="times">
          <div>
            <span>Check In</span>
            <p>{checkIn ? checkIn.toLocaleTimeString() : "--:--"}</p>
          </div>
          <div>
            <span>Check Out</span>
            <p>{checkOut ? checkOut.toLocaleTimeString() : "--:--"}</p>
          </div>
          <div>
            <span>Working Time</span>
            <p>{timer}</p>
          </div>
        </div>

        <div className="buttons">
          <button onClick={handleCheckIn}>Check In</button>
          <button onClick={handleCheckOut}>Check Out</button>
        </div>

        {/* FILTERS */}
        <div className="filters">
          <button onClick={() => setFilter("all")}>All</button>
          <button onClick={() => setFilter("today")}>Today</button>
          <button onClick={() => setFilter("month")}>This Month</button>

          <input type="date" onChange={(e) => setFromDate(e.target.value)} />
          <input type="date" onChange={(e) => setToDate(e.target.value)} />
          <button onClick={() => setFilter("range")}>Apply</button>
        </div>

        {/* HISTORY */}
        <table>
          <thead>
            <tr>
              <th>Date</th>
              <th>Check In</th>
              <th>Check Out</th>
              <th>Hours</th>
            </tr>
          </thead>
          <tbody>
            {filteredHistory.map((item, i) => (
              <tr key={i}>
                <td>{item.date}</td>
                <td>{item.checkIn}</td>
                <td>{item.checkOut}</td>
                <td>{item.hours}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
